import{_ as i,o as e,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Mobile video → Task sync — Spec","description":"","frontmatter":{},"headers":[],"relativePath":"feature/mobile-video-task-sync/spec.md","filePath":"feature/mobile-video-task-sync/spec.md"}'),c={name:"feature/mobile-video-task-sync/spec.md"};function o(h,t,d,l,r,s){return e(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="mobile-video-→-task-sync-—-spec" tabindex="-1">Mobile video → Task sync — Spec <a class="header-anchor" href="#mobile-video-→-task-sync-—-spec" aria-label="Permalink to &quot;Mobile video → Task sync — Spec&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Creator quay video hoặc chọn video/ảnh trên điện thoại; tệp tự lên task. Owner, Manager và Creator thấy tệp ngay trong chi tiết task trên web. Creator chọn take đưa vào bài nháp để Manager duyệt đúng clip.</p><p>Nền tảng: <code>docs/mobile/features/g2-creator-upload</code>.</p><h2 id="user-stories" tabindex="-1">User stories <a class="header-anchor" href="#user-stories" aria-label="Permalink to &quot;User stories&quot;">​</a></h2><ul><li>Creator: quay xong không cần bấm gì thêm, mất mạng hay tắt app vẫn không mất tệp.</li><li>Creator: chọn take tốt nhất đưa vào bài nháp, rồi tự bấm gửi duyệt.</li><li>Manager/Owner: mở task trên web là xem được các take.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ol><li>Sau khi quay/chọn tệp, upload tự chạy khi app đang mở, không cần bấm nút.</li><li>Mất mạng, lỗi tạm thời, hoặc tắt rồi mở lại app: hàng đợi tự chạy lại khi có mạng hoặc app active.</li><li>Có công tắc &quot;Chỉ tải qua Wi-Fi&quot;, mặc định tắt.</li><li>Session hết hạn hoặc bị từ chối thì tạo session mới và upload lại, không kẹt ở confirm. Lỗi vĩnh viễn (định dạng, quyền) hiện rõ, không tự thử lại.</li><li>Có % tiến độ; lỗi hiện đúng thông điệp backend.</li><li>Không tự gửi duyệt. Nút gửi duyệt giữ nguyên ở chi tiết task.</li><li>Task chưa có bài nháp vẫn upload được; giao diện báo &quot;chưa có bài nháp&quot;.</li><li>Ảnh JPEG/PNG/WebP upload được vào task; HEIC đổi sang JPEG trên app.</li><li>File <code>.mov</code> (<code>video/quicktime</code>) và MP4 brand <code>isom</code>/<code>mp42</code> đều qua validate.</li><li>Web: chi tiết task có khu &quot;Tệp từ điện thoại&quot;, tự làm mới, xem trước được. Client không thấy take thô.</li><li>Creator được giao đưa một take vào bài nháp, trên web và mobile. Trước khi task vào duyệt, Client nhận <code>url: null</code> cho take nội bộ tại <code>GET /tasks/{id}/post</code>, và <code>POST_NOT_FOUND</code> tại <code>GET /posts/{id}</code> như quy tắc bài chưa đăng hiện có. Từ khi vào duyệt, Client nhận được URL.</li><li>Màn quay dùng VisionCamera: FPS, chất lượng, chống rung, bù phơi sáng, đèn, zoom là thật. Shutter (khóa phơi sáng) và white balance (khóa theo nhiệt độ màu) là thật và chỉ hiện trên máy báo hỗ trợ. Kính lọc ND, focus peaking, zebra, thước thủy và thanh âm thanh giả bị bỏ. Không tự dừng theo mục tiêu thời lượng.</li><li>Màn quay theo kiểu máy quay chuyên nghiệp (tham chiếu Blackmagic Camera, Sony, Canon): khung máy đen không đè lên hình; dải thông số FPS, Shutter, ISO, WB, Tint, EV luôn hiện, chạm một ô mở dải giá trị của ô đó; ISO và shutter ở chế độ tự động hiện giá trị đọc trực tiếp từ camera. Cột công cụ có đèn, chống rung, lưới, khung, kịch bản, menu; có lấy nét tay và chạm để lấy nét trên máy hỗ trợ. Khi đang quay chỉ đổi được zoom, lấy nét, đèn và kịch bản; có viền tally đỏ. Chỉ hiện điều khiển có tác dụng thật.</li><li>Quay xong ở lại camera để quay take tiếp, giữ nguyên cài đặt; số take nối tiếp theo cảnh và hiện trạng thái tải lên của take vừa quay.</li><li>Vuốt back và nút back Android không thoát được khi đang quay.</li><li>Xoá tệp chưa lên Task phải xác nhận. Từ chối quyền thì có nút Mở Cài đặt.</li><li>Khu take trên mobile mở xem được từng tệp, đặt tên theo cảnh và take, bỏ được tệp khỏi bài ngay tại chỗ, phân biệt lỗi tải với chưa có tệp.</li><li>Android: đồng hồ âm thanh đọc mức thu thật theo dB; danh sách micro đang kết nối và micro hệ thống đang thu. Không có nút chọn micro vì không có tác dụng thật.</li><li>Công cụ đo sáng histogram và zebra đọc từ khung hình thật, chỉ chạy khi bật. Zebra đánh dấu vùng cháy sáng theo ô.</li><li>Màn quay giữ màn hình sáng. App ra nền khi đang quay thì dừng và lưu clip. Lỗi giữa lúc quay thì giữ phần đã quay nếu file phát được; không phát được mới bỏ và báo lỗi.</li><li>Quay xong có nút &quot;Dùng take này&quot; trên Task loại POST: take vào bài nháp ngay khi tải xong, tự tạo nháp nếu chưa có. Không tự gửi duyệt.</li><li>Video vào Task tối đa 4 GB. Bitrate có giới hạn theo chất lượng; gần 4 GB thì cảnh báo, không tự dừng.</li><li>Video lớn tải theo phần: rớt mạng hoặc tắt app thì chỉ gửi lại phần còn thiếu. Lỗi server tự thử lại theo thời gian. Có tiến triển thì không tính vào giới hạn 5 lần thử.</li><li>Android: tải tiếp khi app ra nền, có thông báo tiến độ. iOS: tệp đến 1 GB tải tiếp khi app bị treo, bước xác nhận chạy khi quay lại app; tệp lớn hơn chỉ tải tiếp phần đang gửi.</li><li>Hàng đợi theo từng tài khoản: đăng xuất thì dừng, người đăng nhập sau không thấy và không tải tệp của người trước. Tệp vẫn nằm trên máy đến khi chủ tệp đăng nhập lại.</li></ol><h2 id="api-contract" tabindex="-1">API contract <a class="header-anchor" href="#api-contract" aria-label="Permalink to &quot;API contract&quot;">​</a></h2><ul><li><code>GET /workspaces/{id}/materials?taskId=</code>: lọc theo task. Client vẫn chỉ thấy <code>CLIENT</code> visibility.</li><li><code>POST .../materials/upload-session</code>: TASK nhận thêm ảnh; <code>clientRequestId</code> làm khóa idempotent; TTL 3600s.</li><li><code>POST /workspaces/{id}/tasks/{taskId}/post</code>: đã có, dùng để thêm <code>media[].materialId</code>. Response trả lại <code>media[].materialId</code>.</li><li><code>POST .../materials/upload-session/multipart</code>: video Task đến 4 GiB; body như <code>upload-session</code>; trả <code>sessionId</code>, <code>s3Key</code>, <code>partSize</code>, <code>expiresAt</code>. TTL 24 giờ. Google Drive của khách trả <code>STORAGE_PROVIDER_UNSUPPORTED</code>, app quay về một PUT (giới hạn 1 GiB).</li><li><code>POST .../materials/upload-session/{sessionId}/parts</code>: trả tối đa 8 phần còn thiếu (<code>partNumber</code>, <code>offset</code>, <code>size</code>, <code>url</code>) và <code>uploadedBytes</code>. Danh sách rỗng là đủ phần. App không cần giữ ETag.</li><li><code>POST .../materials/upload-session/confirm</code>: giữ nguyên; tự ghép các phần trước khi kiểm tra tệp, gọi lại được sau khi mất response.</li></ul><h2 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mã</th><th>Xử lý trên mobile</th></tr></thead><tbody><tr><td><code>UPLOAD_SESSION_EXPIRED</code>, <code>UPLOAD_SESSION_NOT_FOUND</code>, <code>UPLOAD_OBJECT_NOT_FOUND</code></td><td>Xóa <code>s3Key</code>, upload lại với <code>clientRequestId</code> mới</td></tr><tr><td><code>TASK_NOT_ASSIGNED</code>, <code>TASK_NOT_ACTIVE</code>, <code>TASK_NOT_FOUND_FOR_UPLOAD</code>, <code>INVALID_UPLOAD_CONTENT_TYPE</code>, <code>UPLOAD_FILE_TOO_LARGE</code>, <code>VALIDATION_ERROR</code></td><td><code>FAILED</code>, không tự thử lại</td></tr><tr><td>Mạng, 5xx, khác</td><td><code>FAILED</code>, tự thử lại khi có sự kiện mạng/active, tối đa 5 lần</td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>Tắt app giữa upload: mục <code>UPLOADING</code>/<code>CONFIRMING</code> về <code>QUEUED</code> khi khởi động.</li><li>Bài đủ 10 media hoặc take đã có trong bài: báo, không gọi API.</li><li>Task không phải <code>IN_PROGRESS</code> hoặc đã khóa: ẩn nút đưa vào bài theo <code>canEdit</code>.</li><li>Chạy trên Expo Go hoặc web: màn quay báo cần dev build, vẫn chọn tệp từ thư viện được.</li></ul><h2 id="ui-states" tabindex="-1">UI states <a class="header-anchor" href="#ui-states" aria-label="Permalink to &quot;UI states&quot;">​</a></h2><p>Mobile: đang chờ, đang tải %, đang xác nhận, xong, lỗi (có nút thử lại). Web: đang tải, rỗng, lỗi, danh sách.</p><h3 id="i18n" tabindex="-1">i18n <a class="header-anchor" href="#i18n" aria-label="Permalink to &quot;i18n&quot;">​</a></h3><p>Web thêm key <code>tasks.phoneMedia.*</code> vào cả <code>vi</code> và <code>en</code>. Mobile có <code>i18n/translations</code> nhưng các màn upload và camera đang dùng chuỗi tiếng Việt trực tiếp; tính năng này giữ nguyên cách đó, chuyển sang key là việc riêng.</p><h3 id="light-dark" tabindex="-1">Light/Dark <a class="header-anchor" href="#light-dark" aria-label="Permalink to &quot;Light/Dark&quot;">​</a></h3><p>Web dùng token theme sẵn có. Các màn của luồng này dùng palette theo theme đang bật (<code>useAppPreferences</code>, <code>ThemedButton</code>, <code>ThemedBadge</code>); màn quay giữ nền tối cố định.</p><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><p>Test tự động pass ở cả 3 repo; luồng API thật pass trên môi trường Docker riêng; checklist thiết bị trong <code>test.md</code> do người dùng xác nhận.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>FPS/shutter ngoài khả năng phần cứng; kính lọc ND; tải tiếp sau khi người dùng tắt hẳn app (mở lại app mới chạy tiếp). Để giai đoạn sau: focus peaking; chọn thủ công micro ghi (VisionCamera không có API, cần thu âm riêng rồi ghép); đồng hồ âm thanh trên iOS.</p>',24)])])}const u=i(c,[["render",o]]);export{p as __pageData,u as default};
